/**
 * Build the WebAssembly kernels.
 *
 * Purpose: compile `assembly/kernels.ts` with SIMD and embed the binary in
 * `src/wasm/kernels.ts` as base64. The generated file is committed, so using
 * or testing the solver never needs the AssemblyScript compiler — only
 * changing a kernel does.
 *
 *   npm run build:wasm
 */

import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const scratch = mkdtempSync(join(tmpdir(), 'kernels-'));
const wasm = join(scratch, 'kernels.wasm');
try {
	execFileSync(
		join(root, 'node_modules', '.bin', 'asc'),
		['assembly/kernels.ts', '--enable', 'simd', '-O3', '--runtime', 'stub', '--importMemory', '--noAssert', '-o', wasm],
		{ cwd: root, stdio: 'inherit' },
	);
	const bytes = readFileSync(wasm);
	const out = `// Generated by scripts/build-wasm.ts from assembly/kernels.ts. Do not edit.
/** The SIMD kernels, ${bytes.length} bytes of WebAssembly. */
export const KERNELS_WASM = '${bytes.toString('base64')}';
`;
	writeFileSync(join(root, 'src', 'wasm', 'kernels.ts'), out);
	console.log(`src/wasm/kernels.ts: ${bytes.length} bytes`);
} finally {
	rmSync(scratch, { recursive: true, force: true });
}
